with card_content(display_order, question_text, question_translation, answer_examples) as (
  values
    (1, 'How are you?', 'Como você está?', '[{"answer":"I''m doing well, thanks. And you?","translation":"Estou indo bem, obrigado/a. E você?","note":"Uma resposta clássica, educada e segura para praticamente qualquer situação, seja formal ou informal."},{"answer":"Not too bad, thanks!","translation":"Nada mal, obrigado/a!","note":"Muito casual e extremamente comum no dia a dia com colegas ou conhecidos."},{"answer":"Can''t complain!","translation":"Não posso reclamar!","note":"Informal, soa natural e transmite uma atitude leve e positiva."},{"answer":"I''m great, thanks for asking!","translation":"Estou ótimo/a, obrigado/a por perguntar!","note":"Excelente para demonstrar entusiasmo, energia ou quando você está num dia especialmente bom."},{"answer":"I''ve been better, to be honest.","translation":"Já estive melhor, para ser sincero/a.","note":"Uma opção para quando você não está tão bem e se sente confortável o suficiente para compartilhar isso com a pessoa que perguntou."}]'::jsonb),
    (2, 'Where are you from?', 'De onde você é?', '[{"answer":"I''m from Brazil.","translation":"Eu sou do Brasil.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''m from Minas Gerais.","translation":"Eu sou de Minas Gerais.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I was born in Brazil.","translation":"Eu nasci no Brasil.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''m originally from a small town.","translation":"Eu sou originalmente de uma cidade pequena.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''m from Brazil, but I''ve lived in different cities.","translation":"Eu sou do Brasil, mas já morei em cidades diferentes.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (3, 'Where do you live?', 'Onde você mora?', '[{"answer":"I live in Uberlândia.","translation":"Eu moro em Uberlândia.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I live in Minas Gerais.","translation":"Eu moro em Minas Gerais.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I live near the city center.","translation":"Eu moro perto do centro da cidade.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I live in a quiet neighborhood.","translation":"Eu moro em um bairro tranquilo.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I live with my family in an apartment.","translation":"Eu moro com minha família em um apartamento.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (4, 'How old are you?', 'Quantos anos você tem?', '[{"answer":"I''m thirty years old.","translation":"Eu tenho trinta anos.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''m twenty-eight.","translation":"Eu tenho vinte e oito anos.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''m in my thirties.","translation":"Eu estou na faixa dos trinta anos.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I just turned forty.","translation":"Eu acabei de fazer quarenta anos.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''ll be thirty-five next month.","translation":"Eu vou fazer trinta e cinco anos no mês que vem.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (5, 'What do you do for work?', 'O que você faz profissionalmente?', '[{"answer":"I''m a teacher.","translation":"Eu sou professor/a.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I work in finance.","translation":"Eu trabalho na área financeira.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''m a software developer.","translation":"Eu sou desenvolvedor/a de software.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I work as an engineer.","translation":"Eu trabalho como engenheiro/a.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''m self-employed and work with consulting.","translation":"Eu trabalho por conta própria com consultoria.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (6, 'Where do you work?', 'Onde você trabalha?', '[{"answer":"I work at a school.","translation":"Eu trabalho em uma escola.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I work for an energy company.","translation":"Eu trabalho para uma empresa de energia.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I work from home most days.","translation":"Eu trabalho de casa na maioria dos dias.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I work at an office downtown.","translation":"Eu trabalho em um escritório no centro.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I work for a company based in São Paulo.","translation":"Eu trabalho para uma empresa sediada em São Paulo.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (7, 'Are you married or single?', 'Você é casado/a ou solteiro/a?', '[{"answer":"I''m single.","translation":"Eu sou solteiro/a.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''m married.","translation":"Eu sou casado/a.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''m in a relationship.","translation":"Eu estou em um relacionamento.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''ve been married for five years.","translation":"Eu sou casado/a há cinco anos.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''m single at the moment.","translation":"Eu estou solteiro/a no momento.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (8, 'What''s your surname?', 'Qual é o seu sobrenome?', '[{"answer":"My surname is Silva.","translation":"Meu sobrenome é Silva.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"It''s Santos.","translation":"É Santos.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"My last name is Oliveira.","translation":"Meu sobrenome é Oliveira.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I have two surnames: Souza and Lima.","translation":"Eu tenho dois sobrenomes: Souza e Lima.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"My family name is Ferreira.","translation":"Meu sobrenome de família é Ferreira.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (9, 'How do you spell your name?', 'Como se soletra o seu nome?', '[{"answer":"It''s A-N-A.","translation":"É A-N-A.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"M-A-R-C-O-S.","translation":"M-A-R-C-O-S.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Let me spell it: L-U-C-A-S.","translation":"Deixe-me soletrar: L-U-C-A-S.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"It''s J-U-L-I-A, with a J.","translation":"É J-U-L-I-A, com J.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Sure. It''s R-A-F-A-E-L.","translation":"Claro. É R-A-F-A-E-L.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (10, 'What is your full name?', 'Qual é o seu nome completo?', '[{"answer":"My full name is Ana Silva.","translation":"Meu nome completo é Ana Silva.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"It''s Carlos Eduardo Santos.","translation":"É Carlos Eduardo Santos.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"My name is Mariana Souza Lima.","translation":"Meu nome é Mariana Souza Lima.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"My full name is Rafael Oliveira Costa.","translation":"Meu nome completo é Rafael Oliveira Costa.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It''s Beatriz Fernandes Alves.","translation":"É Beatriz Fernandes Alves.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb)
)
update public.conversation_questions as question
set question_text=content.question_text, question_translation=content.question_translation, answer_examples=content.answer_examples
from card_content as content
where question.display_order=content.display_order;
